        const classPortraits = Object.fromEntries(Object.entries(classDefaultPortraitIds).map(([name,id]) => [name, getCharacterPortraitV2135(id)]));
        const classCards = Object.keys(CLASS_DATA).map(name => { const v = classVisuals[name] || { icon: "✦", tone: "mystic", desc: "مسیر تخصصی این کلاس در حال آماده‌سازی است" }; const portrait = classPortraits[name]; return `<button type="button" class="origin-class-card ${name === 'جنگجو' ? 'is-selected' : ''}" data-class-choice="${esc(name)}" aria-pressed="${name === 'جنگجو' ? 'true' : 'false'}"><span class="origin-class-art ${v.tone}">${portrait ? `<img src="${portrait}" alt="پرتره ${esc(name)}" loading="eager">` : `<span class="class-sigil">${v.icon}</span><i class="class-silhouette"></i>`}</span><span class="origin-class-copy"><b>${esc(name)}</b><small>${esc(v.desc)}</small><em>۴ تخصص</em></span><span class="class-check">✦</span></button>`; }).join('');
